// ===== CONFIGURATION =====
const DEBUG_MODE = global.get("DEBUG_MODE") || false;  // Activer/désactiver les logs
const sousFlowExclus = "SousFlow_UI_Change";         // Nom du sous-flow à ne pas désactiver

// ===== RÉCUPÉRATION ÉTAT COURANT =====
const pageCourante = global.get('pageCourante') || "Accueil";
const flowCourant = global.get('flowCourant') || "Principal";
const sousFlowCourant = global.get('sousFlowCourant') || "A_Definir";

// ===== INITIALISATION MESSAGES =====
msg.dashboard = [];
let redirectNeeded = false;

// ===== JOURNALISATION (SI DEBUG) =====
if (DEBUG_MODE) {
    node.warn(`État actuel -> Page: ${pageCourante}, Flow: ${flowCourant}, Sous-Flow: ${sousFlowCourant}`);
    node.warn(`Nouvelle cible -> Page: ${msg.payload.nouvellePage}, Flow: ${msg.payload.nouveauFlow}`);
}

// ===== VÉRIFICATION CHANGEMENTS =====
// 1. Page
if (msg.payload.nouvellePage && msg.payload.nouvellePage !== pageCourante) {
    msg.dashboard.push({ show: false, page: pageCourante });
    global.set('pageCourante', msg.payload.nouvellePage);
    redirectNeeded = true;
}

// 2. Flow principal
if (msg.payload.nouveauFlow && msg.payload.nouveauFlow !== flowCourant) {
    flow.set(`${flowCourant}Actif`, false);
    flow.set(`${msg.payload.nouveauFlow}Actif`, true);
    global.set('flowCourant', msg.payload.nouveauFlow);
}

// 3. Sous-flow (avec exclusion)
if (msg.payload.nouveauSousFlow && msg.payload.nouveauSousFlow !== sousFlowCourant) {
    if (sousFlowCourant !== "A_Definir" && sousFlowCourant !== sousFlowExclus) {
        flow.set(`${sousFlowCourant}Actif`, false);
    }
    flow.set(`${msg.payload.nouveauSousFlow}Actif`, true);
    global.set('sousFlowCourant', msg.payload.nouveauSousFlow);
}

// ===== AFFICHAGE NOUVELLE PAGE =====
msg.dashboard.push({ show: true, page: msg.payload.nouvellePage });

// ===== REDIRECTION NAVIGATEUR (SI NÉCESSAIRE) =====
if (redirectNeeded && msg.payload.redirect) {
    msg.http = {
        statusCode: 302,
        headers: { "Location": `/dashboard/${msg.payload.nouvellePage}` },
        payload: ""
    };
    if (DEBUG_MODE) node.warn("Redirection vers: " + msg.http.headers.Location);
}

// ===== RETOUR DES MESSAGES =====
if (msg.http) {
    return [msg.dashboard, msg.http];  // Double sortie
} else {
    return msg.dashboard;              // Sortie simple
}

//Ici configuration des valeurs par defaut de l'IP suivant le contexte
// Le sous-menu à permis de choisir le mode de fonctionnement
//var ipcourante= global.set("Ip_Courante"); // ?
// Exécuter uniquement si le bouton a envoyé "reset" ou si IP_Courante existe
//if (msg.payload !== "reset" || msg.payload!=="$ConnectIP#" ) return null;

//Constructeur avec jsDoc pour documentation si VS Code autocomplétion
/**
 * Constructeur d'une entrée IP.
 * @param {string} id - Identifiant unique.
 * @param {string} ip - Adresse IPv4.
 * @param {string} description - Description.
 * @param {"disponible"|"indisponible"|"connecté"|"non défini"} etat - Statut.
 */
function ConstrucIP (id, ip, description, etat) {
    this.id = id;
    this.ip = ip;
    this.description = `Adresse IP : ${ip} - Cas : ${id} - ${description} `; // ok si Template literal (ES6)
    this.etat = etat;
}
// Vérification initiale critique
if (!msg.payload || typeof msg.payload !== "object") {
    node.error("Message invalide : payload manquant ou non objet", msg);
    return null;
}
// Test de l'existence de ipListe (le futur tableau d'info. sur les IP)
let ipListe = global.get("ipListe") || []; // Initialise avec un tableau vide si non existant

// Si la variable n'existe pas OU n'est pas un tableau OU est vide
if (!Array.isArray(ipListe) || ipListe.length === 0) {

    /** 
         * Crée un tableau d'IPs pour un menu dropdown.
         * @output msg.payload {Array<{id: string, ip: string, description: string, etat: string}>}
         */
    ipListe = [
        new ConstrucIP(
            "SmartP_IP_Direct",
            "192.168.48.xx",//remplacer par la valeur correcte
            "Smartphone (partage de connexion) - Activez le partage de connexion sur le smartphone embarqué",
            "indéfini"
            ),
        new ConstrucIP(
            "RPI_IP_Wifi",
            "192.168.1.40",//cas serveur maison zz adresse reseau etho 40 wifi 37
            "Serveur RPI sur réseau local (connecté à la box maison)",
            "non défini"
            )
        ];

    // Initialiser un tableau pour stocker les adresses locales recherchées
    let localIPs = [];

    // Parcourir toutes les interfaces réseau pour avoir un tableau des adresses locales IPV4
    for (const [interfaceName, interfaceData] of Object.entries(msg.payload.networkInterfaces)) {
        // Filtrer les adresses IPv4 commençant par 192.168
        const filtered = interfaceData.filter(item => {
            return item.family === "IPv4" && item.address.startsWith("192.168");
        });
        // Ajouter les résultats au tableau final
    localIPs.push(...filtered.map(ipObj => ipObj.address)); // Récupère uniquement les adresses
    }

    // Gestion des résultats IP (pour info exple chemin : payload.networkInterfaces.wlan0[3].address)
    if (localIPs.length === 1) {
        const ipLocale = new ConstrucIP("SmartPiloteViaBox", localIPs[0], "Le smartphone pilote utilise une adresse fourni par la box","connecté" );
        ipListe.push(ipLocale);
    } 
    else if (localIPs.length < 1) {
        const ipLocale = new ConstrucIP("SmartPiloteViaBox", "", "Aucune adresse IP 192.168 trouvée", "indisponible");
        ipListe.push(ipLocale);
    } 
    else {
        //Ajouter les IPs locales avec vos règles spécifiques
        localIPs.forEach((ip, index) => {
            ipListe.push(
                new ConstrucIP(
                    `SmartPiloteViaBox-${index + 1}`, // ID auto-incrémenté
                    ip,
                    "IP local disponible", // Description commune
                    "indéfini" // État fixe
                )
            );
        });
    };

    // Cherche si la liaison par internet distant existe :
    if (msg.payload.publicIPV4) {
        ipListe.push(
            new ConstrucIP(
            "RPI_IP_Serveur",
            msg.payload.publicIPV4,
            "Serveur RPI distant exposé Internet - (Nécessite une carte SIM sur le Smartphone embarqué)",
            "disponible"
            )
        );
    }
    else{

        ipListe.push(
            new ConstrucIP(
             "RPI_IP_Serveur",
             "",
             "Serveur RPI distant exposé Internet - (Nécessite une carte SIM sur le Smartphone embarqué)",
             "indisponible"
            )
        );
    };
    //conserver la dernière liste validée
    global.set("ipListe", ipListe, "file"); // stockage persistant
    global.set("ipListe", ipListe); // actualiser globale courant
    msg.payload = ipListe;

}

return msg;

const liste = global.get("ipListe") || [];

// Vérifie qu'on a bien un tableau
if (!Array.isArray(liste)) {
    node.warn("ipListe n'est pas un tableau !");
    return null;
}

msg.ui_update = {
    options: liste.map(ip => ({
        label: `${ip.description} [${ip.etat}]`,
        value: ip.id
    }))
};

msg.payload = null;
return msg;

// Récupère l’ID sélectionné
const selectedId = flow.get("ipSelectionTemp");
const ipListe = global.get("ipListe") || [];

// Marquer tous à leur état initial sauf celui sélectionné
ipListe.forEach(ip => {
    if (ip.id === selectedId) {
        ip.etat = "ipCourante";
        global.set("Ip_Courante", ip.ip);// actualise l'IP_Courante ds global
        msg.payload = `IP actuelle : ${ip.ip}`;
        msg.topic = "Connexion"
    } else if (ip.etat === "ipCourante") {
        ip.etat = "disponible"; // ou garder l'état précédent
    }
});

// Mise à jour globale
global.set("ipListe", ipListe);
global.set("ipListe", ipListe, "file");// je l'inclus ds la mémoire stable
return msg;

//Affichage du groupe Grpe_On_Choix_IP
//Déf affichage
msg = {
    payload: {
        pages: {
            show: ["P_Accueil"],
            focus: "P_Accueil"
        },
        groups: {
            show: ["Grpe_On_Choix_IP"],
        }
    },
    topic: "ip"
};

return msg;

/*
 * NOM       : Règles minimales V1
 * SOUS-FLOW : SF_ReglesMinimales_V1
 * CHEMIN    : Node-RED SP → tab Gtion_EtatGlobal_V1 → subflow SF_ReglesMinimales_V1
 *
 * OBJECTIF
 * --------
 *   Appliquer les règles non configurables liées au mode (modeRZ) et au
 *   type de pilotage (typePtge) : commandes autorisées selon le
 *   contexte, transitions interdites, indicateurs UI reflétant les
 *   capacités réelles du système.
 *
 * SORTIES : 3
 *   0 — chemin normal → SF_ValidationIntent_V1
 *   1 — link out vers li_evt_start (tab Gtion_Init), déclenche SF_Init_1
 *   2 — msg.ack (FAIL) → instance de SF_EmissionACK, UNIQUEMENT si le
 *       message rejeté porte msg.origine='STT' et msg.stt_id_requete
 *
 * PRINCIPES (repris de la V1 d'origine)
 * ---------------------------------------
 *   - CfgS est la variable maîtresse.
 *   - Aucun effet matériel direct ici : uniquement mise à jour de la
 *     mémoire vive (global.RZ_<VAR> et indicateurs flag_* / ui_*).
 *   - (2.2) STRUCTURE EN DEUX PHASES : tests de rejet d'abord, sans
 *     effet de bord, puis effets de bord uniquement si rien rejeté.
 *   - (2.4) msg.cfgCible = {modeRZ, typePtge}, si présent, utilisé en
 *     priorité sur la valeur confirmée pour le champ non modifié par le
 *     message courant (évite un rejet à tort sur double-envoi rapproché).
 *
 * PRÉCAUTIONS / CORRECTIFS
 * --------------------------
 *   (05/07, 07/07, 13/07, 06/08/2026 — cfgCible) — voir versions
 *     précédentes pour l'historique complet.
 *   (06/08/2026, ACK rejet) NOUVELLE SORTIE : tout rejet (R2/R4/R6/R7/
 *     R11/R13) sur un message d'origine STT avec un id_requete émet
 *     désormais un ACK FAIL vers SE, raison = code de la règle qui a
 *     rejeté (ex: "R2"). AVANT ce correctif, un rejet ici pour un intent
 *     STT nécessitant une résolution SP se traduisait uniquement par un
 *     timeout silencieux de 4s côté SE (wait_for_ack), sans jamais
 *     savoir pourquoi. Les messages sans origine STT ou sans
 *     id_requete (Mtr direct, UI, capteurs...) sont inchangés — jamais
 *     d'ACK émis pour eux.
 *
 * VERSION : 2.5 - 06/08/2026 - Vincent Philippe (correctif Claude)
 */

const rzCfgS = global.get('RZ_CfgS') || {};

function lireCfgS(prop) {
    const p = rzCfgS[prop];
    if (!p) return undefined;
    return p._last !== undefined ? p._last : p['*'];
}

const modeRZ = lireCfgS('modeRZ');
const typePtge = lireCfgS('typePtge');
const v = msg.vpiv;

const cible = msg.cfgCible;

const modeRZEff = (v.var === 'CfgS' && v.prop === 'modeRZ')
    ? v.val
    : (cible && cible.modeRZ !== undefined ? cible.modeRZ : modeRZ);

const typePtgeEff = (v.var === 'CfgS' && v.prop === 'typePtge')
    ? v.val
    : (cible && cible.typePtge !== undefined ? cible.typePtge : typePtge);

const modeRestreint = ['4', '2'].includes(modeRZEff);
const flagMoteurDispoEff = !modeRestreint;
const laisseValide = ['3', '4'].includes(typePtgeEff) && modeRZEff === '3';

/* R3 — RESET SYSTÈME → délégué à SF_Init_1 (routage, pas un rejet) */
if (v.var === 'CfgS' && v.prop === 'reset' &&
    (v.val === true || v.val === 1 || v.val === '1')) {
    node.warn('R3 : reset demandé — délégué à SF_Init_1 via li_evt_start');
    return [null, msg, null];
}

let rejet = null;

if (modeRZ === '0' && v.var === 'Mtr') {
    rejet = { code: 'R2', message: 'commande moteur rejetée (mode ARRET)' };
}
else if (modeRZ === '4' && v.var === 'Mtr') {
    rejet = { code: 'R4', message: 'commande moteur ignorée (mode AUTONOME)' };
}
else if (modeRZ === '2' && v.var === 'Mtr') {
    rejet = { code: 'R6', message: 'commande moteur rejetée (mode FIXE)' };
}
else if (['3', '4'].includes(typePtgeEff) && modeRZEff !== '3' &&
    v.var === 'CfgS' && v.prop === 'typePtge') {
    rejet = { code: 'R7', message: `combinaison interdite typePtge=${typePtgeEff} / modeRZ≠DEPLACEMENT` };
}
else if (typePtgeEff === '2' && modeRZEff === '2' && v.var === 'Mtr') {
    rejet = { code: 'R7', message: 'commande moteur rejetée (JOYSTICK + FIXE)' };
}
else if (v.var === 'CfgS' && v.prop === 'modeRZ') {
    const transitionsInterdites = [{ from: '0', to: '3' }];
    if (transitionsInterdites.some(t => t.from === modeRZ && t.to === v.val)) {
        rejet = { code: 'R11', message: `transition interdite ${modeRZ} → ${v.val}` };
    }
}

if (!rejet && v.var === 'Mtr' && !flagMoteurDispoEff) {
    rejet = { code: 'R13', message: 'commande moteur bloquée (moteur indisponible pour ce mode)' };
}

if (rejet) {
    node.warn(`${rejet.code} : ${rejet.message}`);
    if (msg.origine === 'STT' && msg.stt_id_requete) {
        msg.ack = { var: 'STT', prop: 'intent', id_requete: msg.stt_id_requete, statut: 'FAIL', raison: rejet.code };
        return [null, null, msg];
    }
    return [null, null, null];
}

if (typePtgeEff === '2' && modeRZEff === '2') {
    global.set('flag_deplacement_autorise', false);
    global.set('flag_servos_autorises', true);
}

global.set('ui_affichage_joystick_virtuel', !!typePtgeEff && !['3', '4'].includes(typePtgeEff));

global.set('flag_moteur_dispo', flagMoteurDispoEff);
global.set('flag_odom_dispo', flagMoteurDispoEff);
global.set('flag_laisse_active', laisseValide);
global.set('flag_servos_autorises', true);
global.set('flag_capteurs_autorises', true);
global.set('ui_grp_pilotage_moteur', flagMoteurDispoEff);

global.set('ui_autorise_pilotage_moteur', global.get('flag_moteur_dispo'));
global.set('ui_autorise_pilotage_servos', global.get('flag_servos_autorises'));
global.set('ui_autorise_capteurs', global.get('flag_capteurs_autorises'));

msg._validatedBy = 'SF_ReglesMinimales_V1';
msg._timestamp = Date.now();
return [msg, null, null];

/*
 * NOM       : fct_detect_urgence — R0 : Détection d'urgence
 * SOUS-FLOW : SF_GestionUrgence
 * CHEMIN    : Node-RED SP → tab Gtion_EtatGlobal_V1 → subflow SF_GestionUrgence
 *
 * OBJECTIF
 * --------
 *   Détecter qu'une trame CAT=E (urgence — Table A : "Événement critique,
 *   réaction automatique SP") vient d'arriver, et maintenir l'état
 *   "urgence active" dans la mémoire vive SP (global.RZ_Urg.statut), qui
 *   fait autorité pour le reste de la chaîne (R1, R2, et plus loin
 *   SF_ReglesMinimales si jamais il doit aussi vérifier cet état).
 *
 * ARTICULATION
 * ------------
 *   Entrée  : msg.vpiv, garanti valide par SF_Dispatcher_EtatGlobal.
 *   Sortie  : msg.urgence = { active, cause } → lu par R1 (fct_apply_urgence).
 *
 * PRÉCAUTIONS
 * -----------
 *   - CORRECTIF (04/07/2026) : lisait auparavant msg.eventType/msg.payload
 *     (ancien format théorique, jamais réellement branché).
 *   - HYPOTHÈSE À CONFIRMER : l'arrêt physique des moteurs en urgence est
 *     un réflexe Arduino autonome (SecMvt, mode hard — Table A). Ce
 *     sous-flow ne renvoie donc PAS de commande VPIV vers le matériel,
 *     seulement l'état SP (mémoire vive + routage). Si ce n'est pas le
 *     cas, il faudra revoir ce fichier.
 *
 * VERSION : 2.0 - 04/07/2026 - Vincent Philippe (correctif Claude)
 */

const v = msg.vpiv;

// --- État d'urgence actuellement connu par SP (mémoire vive) ---
let rzUrg = global.get('RZ_Urg') || {};
const dejaActive = !!(rzUrg.statut && (rzUrg.statut['*'] === 'active' || rzUrg.statut._last === 'active'));

let urgence = dejaActive;
let cause = dejaActive ? (rzUrg.source && (rzUrg.source['*'] || rzUrg.source._last)) : null;

// --- Nouvelle urgence détectée sur CE message (CAT=E) ---
if (v && v.cat === 'E') {
    urgence = true;
    cause = `${v.var}.${v.prop} = ${v.val}`;

    rzUrg.statut = rzUrg.statut || {};
    rzUrg.statut['*'] = 'active';
    rzUrg.statut._last = 'active';
    global.set('RZ_Urg', rzUrg);

    node.warn(`R0 : urgence détectée — ${cause}`);
}

msg.urgence = { active: urgence, cause };
return msg;

/*
 * NOM       : fct_clear_urgence — R2 : Levée d'urgence
 * SOUS-FLOW : SF_GestionUrgence
 *
 * OBJECTIF
 * --------
 *   Reconnaître la commande Urg.clear (Table A : SP→SE et SP→A,
 *   $V:Urg:clear:*:1#) et lever l'urgence dans la mémoire vive SP.
 *   Annule le routage "URGENCE" posé par R1 pour que cette commande de
 *   levée suive le chemin normal de validation, pas le bypass.
 *
 * ARTICULATION
 * ------------
 *   Sortie : sw_sortie (switch sur msg.route) — inchangé, "URGENCE" vers
 *   la sortie directe, sinon vers SF_ReglesMinimales.
 *
 * VERSION : 2.0 - 04/07/2026 - Vincent Philippe (correctif Claude)
 */

if (msg.vpiv && msg.vpiv.var === 'Urg' && msg.vpiv.prop === 'clear') {
    let rzUrg = global.get('RZ_Urg') || {};
    rzUrg.statut = rzUrg.statut || {};
    rzUrg.statut['*'] = 'cleared';
    rzUrg.statut._last = 'cleared';
    global.set('RZ_Urg', rzUrg);

    msg.urgence = { active: false, cause: null };
    delete msg.route;   // annule le routage posé par R1, le cas échéant

    node.warn('R2 : urgence levée par commande Urg.clear');
}

return msg;

// R0 – Chargement des règles dynamiques
// -------------------------------------
// Règles stockées côté Node-RED (admin)
// Format attendu (V1 simplifié) :
// [ { id, condition(ctx), action(ctx) } ]

let rules = global.get("rulesDynV1") || [];

msg.rulesDyn = Array.isArray(rules) ? rules : [];
return msg;

// R1 – Application des règles dynamiques (STUB)
// ----------------------------------------------
// Chaque règle :
// - teste une condition
// - applique une action non critique

let ctx = {
    modeRZ: global.get("modeRZ"),
    typePtge: global.get("typePtge"),
    urgenceActive: global.get("urgenceActive") === true
};

let applied = [];

for (let rule of msg.rulesDyn) {
    try {
        // STUB : à remplacer par vrai moteur de règles
        if (typeof rule === "object" && rule.enabled === true) {
            applied.push(rule.id || "rule_sans_id");
        }
    } catch (e) {
        node.warn("Erreur règle dynamique : " + e.message);
    }
}

if (applied.length > 0) {
    msg.infoDyn = {
        appliedRules: applied,
        ctx
    };
    msg.route = "INFO";
}

return msg;

/*
 * NOM       : fn_validate_intent — Validation Intent V1
 * SOUS-FLOW : SF_ValidationIntent_V1
 * CHEMIN    : Node-RED SP → tab Gtion_EtatGlobal_V1 → subflow SF_ValidationIntent_V1
 *
 * OBJECTIF
 * --------
 *   Valider les messages porteurs d'une intention utilisateur explicite
 *   (msg.origine défini : "STT" aujourd'hui, "UI" une fois ui_Accueil_v3
 *   migré), et produire un Plan d'Actions minimal (msg.planActions).
 *   Tout message SANS msg.origine (trafic Bus normal, ACK, capteurs)
 *   traverse sans arbitrage — ce n'est pas une "intention" à valider.
 *
 * ⚠️ IMPORTANT — CE QUE CE FICHIER NE FAIT PAS (volontairement)
 * ----------------------------------------------------------------
 *   L'arbitrage Cmde / Conv / Mixte (faut-il traiter cette parole comme
 *   une commande ou une conversation libre ?) est décidé ENTIÈREMENT
 *   CÔTÉ SE, en amont, dans rz_autovoice_bridge.sh v3.0 ("Architecture
 *   Option B", validée et testée le 21/06/2026 — voir stt_voice_V2.html).
 *   Si SP reçoit une capsule STT.intent, c'est la preuve que SE a déjà
 *   décidé qu'il s'agissait d'une commande — le contexte "Conv" ne
 *   produit jamais d'intent, une conversation libre part directement
 *   vers Gemini sans jamais transiter par ce fichier. Ne PAS réintroduire
 *   ici une logique Cmde/Conv/Mixte qui dupliquerait une décision déjà
 *   prise et déjà testée côté SE.
 *
 * ARTICULATION
 * ------------
 *   Entrée  : msg.vpiv (garanti par SF_Dispatcher_EtatGlobal), précédé
 *             par SF_GestionUrgence et SF_ReglesMinimales_V1 — les
 *             restrictions liées au mode (ARRET/FIXE/AUTONOME) sont déjà
 *             appliquées en amont, pas à refaire ici.
 *   Sortie  : vers SF_Stabilisation_V1.
 *
 * PRÉCAUTIONS / CORRECTIFS
 * ----------------------------------------
 *   (06/08/2026) BUG TROUVÉ EN TEST RÉEL : la lecture de RZ_STT.context
 *     faisait `rzSTT.context['*'] || rzSTT.context._last` — donc lisait
 *     '*' EN PRIORITÉ. Or '*' n'est jamais mis à jour par le trafic réel
 *     pour une propriété à instance générique (seul _last l'est, comme
 *     déjà trouvé pour CfgS.modeRZ/typePtge le 13/07 et le 06/08) — '*'
 *     reste figé sur "Inactif" (valeur de démarrage) indéfiniment. Toute
 *     intention STT était donc TOUJOURS refusée ici, quel que soit le
 *     vrai contexte calculé côté SE. Corrigé : _last prioritaire,
 *     identique au correctif déjà appliqué à lireCfgS().
 *   (05/07/2026) BUG CORRIGÉ : la version précédente faisait `msg.validation =
 *     "REFUSED"` puis `return msg;` dans tous les cas de refus — le
 *     message continuait quand même jusqu'au matériel (confirmé par
 *     test réel). Un refus bloque désormais réellement (`return null`).
 *   (05/07/2026) Vérifications de mode (ARRET/FIXE/AUTONOME sur Mtr) RETIRÉES —
 *     redondantes avec SF_ReglesMinimales_V1, qui les applique déjà à
 *     toute commande Mtr quelle que soit son origine.
 *   (05/07/2026) Migration msg.intent (ancien format, jamais rempli) →
 *     msg.vpiv + msg.origine (rempli par fn_stt_intent_router depuis le
 *     05/07/2026).
 *   (05/07/2026) global.get("modeRZ")/("modePtge")/("STT_active") (clés
 *     inventées, jamais alimentées) remplacés par global.RZ_STT, cohérent
 *     avec le reste du projet.
 *
 * VERSION : 2.1 - 06/08/2026 - Vincent Philippe (correctif Claude)
 */

