const v = msg.vpiv;
const CATS_VALIDES = new Set(['V', 'I', 'E', 'F', 'A']);

// --- Validation de la forme canonique VPIV ---
if (!v || typeof v !== 'object') {
    node.warn('Dispatcher : message rejeté — msg.vpiv absent (ancien format théorique ?)');
    return null;
}

if (!v.var || !v.prop) {
    node.warn(`Dispatcher : message rejeté — msg.vpiv incomplet (var=${v.var}, prop=${v.prop})`);
    return null;
}

if (!v.cat || !CATS_VALIDES.has(v.cat)) {
    node.warn(`Dispatcher : message rejeté — CAT invalide (${v.cat})`);
    return null;
}

// --- Normalisation légère (valeur par défaut d'instance, rien de métier) ---
v.inst = v.inst || '*';
// val peut légitimement être 0, false ou "" → pas de défaut forcé ici

// --- Enveloppe générique (même principe qu'avant la migration) ---
msg.meta = msg.meta || {};
msg.meta.topic = msg.meta.topic || msg.topic || null;
msg.meta.origin = msg.meta.origin || 'RZ_GestionFlux';
msg.timestamp = msg.timestamp || Date.now();

// --- Nettoyage de l'ancien format théorique, s'il traîne encore ---
delete msg.source;
delete msg.eventType;
delete msg.intent;
delete msg.urgent;
delete msg.priority;

