// ==================================================
// SF_Dispatcher_EtatGlobal – V1 CORRIGÉ
// Rôle : garantir le format canonique RAW
// AUCUNE interprétation
// ==================================================

// --- Source ---
if (!msg.source) {
    msg.source = "UNKNOWN";
}

// --- Event type ---
msg.eventType = "RAW";

// --- Intent ---
if (!msg.intent) {
    msg.intent = "UNKNOWN";
}

// --- Payload ---
if (!msg.payload) {
    msg.payload = {};
}

// --- Meta ---
msg.meta = msg.meta || {};
msg.meta.topic = msg.meta.topic || msg.topic || null;
msg.meta.origin = msg.meta.origin || "RZ_GestionFlux";

// --- Timestamp ---
msg.timestamp = msg.timestamp || Date.now();

// Nettoyage minimal (on ne détruit rien d’utile)
delete msg.urgent;
delete msg.priority;

return msg;

/*
 * NOM       : fn_validate_intent — Validation Intent V1
 * SOUS-FLOW : SF_ValidationIntent_V1
 * CHEMIN    : Node-RED SP → tab Gtion_EtatGlobal_V1 → subflow SF_ValidationIntent_V1
 *
 * OBJECTIF
 * --------
 *   Valider les messages porteurs d'une intention utilisateur explicite
