 * VERSION : 2.2 - 06/08/2026 - Vincent Philippe (correctif Claude)
 */

if (!msg.origine) {
    msg.validation = 'OK';
    return msg;
}

if (msg.origine === 'STT') {
    const rzSTT = global.get('RZ_STT') || {};
    const context = (rzSTT.context && (rzSTT.context._last !== undefined ? rzSTT.context._last : rzSTT.context['*'])) || 'Inactif';

    if (context === 'Inactif') {
        msg.validation = 'REFUSED';
        msg.refusalReason = 'STT_CONTEXT_INACTIF';
        node.warn('SF_ValidationIntent : intent STT refusé — contexte Inactif (arrivée tardive ?)');
        if (msg.stt_id_requete) {
            msg.ack = { var: 'STT', prop: 'intent', id_requete: msg.stt_id_requete, statut: 'FAIL', raison: 'STT_CONTEXT_INACTIF' };
            return [null, msg];
        }
        return null;
    }

    msg.validation = 'OK';
    msg.planActions = [msg.vpiv];
    return msg;
}

msg.validation = 'OK';
return msg;

/*
 * NOM      : Construire + valider trame ACK
 * CHEMIN   : Node-RED SP → sous-flow SF_EmissionACK
 *
 * OBJECTIF
 * --------
 *   Construire une trame VPIV ACK (CAT=I) a publier vers SE, en
 *   reutilisant INST pour porter l'id_requete de correlation. Generique
 *   - pas specifique a STT.
 *
 * ENTREE ATTENDUE (msg.ack)
 * --------------------------
 *   {
 *     var: "STT",          // VAR de la trame ACK (miroir de la commande d'origine)
 *     prop: "intent",       // PROP (idem : meme PROP que la commande recue)
 *     id_requete: "req...", // correlation - porte par INST dans la trame
 *     statut: "OK"|"FAIL",
 *     raison: "..."         // optionnel, uniquement pertinent si statut=FAIL
 *   }
 *
 * SORTIE
 * ------
 *   msg.payload = "$I:VAR:PROP:id_requete:valeur#"
 *   msg.topic   = "SE/commande"
 *
 * PRECAUTIONS
 * -----------
 *   - NE PAS cabler cette sortie vers fn_encoder_router_v3 / MQTT OUT ->
 *     Hardware : ce noeud filtre volontairement tout msg.vpiv.cat != V/A
 *     (garde-fou anti-boucle ACK) - une trame CAT=I y serait bloquee en
 *     silence. Cabler vers le noeud MQTT OUT dedie (prochaine etape).
 *   - Si msg.ack est absent ou incomplet, ce noeud n'emet rien (node.warn)
 *     plutot que de publier une trame VPIV mal formee.
 *
 * VERSION : 1.0 - 07/07/2026 - Vincent Philippe / Claude
 */

const ack = msg.ack;

if (!ack || !ack.var || !ack.prop || !ack.id_requete || !ack.statut) {
    node.warn('Construire ACK : msg.ack incomplet - trame non emise. Recu : ' + JSON.stringify(ack));
    return null;
}

if (!['OK', 'FAIL'].includes(ack.statut)) {
    node.warn('Construire ACK : statut invalide (' + ack.statut + ') - attendu OK ou FAIL.');
    return null;
}

let valeur = ack.statut;
if (ack.statut === 'FAIL' && ack.raison) {
    valeur = `${ack.statut},${ack.raison}`;
}

msg.payload = `$I:${ack.var}:${ack.prop}:${ack.id_requete}:${valeur}#`;
msg.topic = 'SE/commande';

return msg;

/*
