const modeRZStage = flow.get('staged_modeRZ');
const typePtgeStage = flow.get('staged_typePtge');

const modeRZCible = (modeRZStage !== undefined) ? modeRZStage : modeRZActuel;
const typePtgeCible = (typePtgeStage !== undefined) ? typePtgeStage : typePtgeActuel;

const changeModeRZ = (modeRZStage !== undefined && modeRZStage !== modeRZActuel);
const changeTypePtge = (typePtgeStage !== undefined && typePtgeStage !== typePtgeActuel);

if (!changeModeRZ && !changeTypePtge) {
    node.warn('Valider : aucun changement a envoyer');
    return null;
}

function estLaisse(tp) { return ['3', '4'].includes(tp); }
function trame(prop, val) {
    return {
        vpiv: { cat: 'V', var: 'CfgS', prop, inst: '*', val },
        origine: 'UI',
        cfgCible: { modeRZ: modeRZCible, typePtge: typePtgeCible }
    };
}

const msgs = [];
if (estLaisse(typePtgeCible)) {
    if (changeModeRZ) msgs.push(trame('modeRZ', modeRZCible));
    if (changeTypePtge) msgs.push(trame('typePtge', typePtgeCible));
} else if (estLaisse(typePtgeActuel) && changeModeRZ) {
    if (changeTypePtge) msgs.push(trame('typePtge', typePtgeCible));
    if (changeModeRZ) msgs.push(trame('modeRZ', modeRZCible));
} else {
    if (changeModeRZ) msgs.push(trame('modeRZ', modeRZCible));
    if (changeTypePtge) msgs.push(trame('typePtge', typePtgeCible));
}

flow.set('staged_modeRZ', undefined);
flow.set('staged_typePtge', undefined);
node.status({ fill: 'green', shape: 'dot', text: msgs.length + ' commande(s) envoyee(s)' });
node.log('Valider : ' + msgs.map(m => m.vpiv.prop + '=' + m.vpiv.val).join(' puis '));

return [msgs];

/*
 * NOM    : UI_Sync_Etat_Confirme
 * TAB    : ui_Accueil_v3
 * ROLE   : Sortie 1 -> InfoSpe (confirmation mode/pilotage, texte
 *          combine). Sortie 2 -> badge Mode (bandeau). Sortie 3 ->
 *          badge Pilotage (bandeau). Une seule lecture globale,
 *          partagee entre les trois affichages -- pas de duplication
 *          de logique entre widgets.
 * VERSION: 1.0 - 06/08/2026 - Vincent Philippe / Claude
 */
const LABELS_MODE_RZ = {
    '0': '⏹️ ARRET', '1': '🌙 VEILLE',
    '2': '📍 FIXE', '3': '🚶 DEPLACEMENT',
    '4': '🤖 AUTONOME', '5': '⚠️ ERREUR'
};
const LABELS_TYPE_PTGE = {
    '0': '🖥️ ECRAN', '1': '🎙️ VOCALE',
    '2': '🎮 JOYSTICK', '3': '🦮 LAISSE',
    '4': '🦮🎙️ LAISSE+VOCALE'
};

const rzCfgS = global.get('RZ_CfgS') || {};
function lireCfgS(prop) {
    const p = rzCfgS[prop];
    if (!p) return undefined;
    return p._last !== undefined ? p._last : p['*'];
}

const modeRZ = lireCfgS('modeRZ');
const typePtge = lireCfgS('typePtge');

const modeLabel = LABELS_MODE_RZ[modeRZ] || 'inconnu';
const ptgeLabel = LABELS_TYPE_PTGE[typePtge] || 'inconnu';

const msgInfoSpe = { payload: `Mode confirme : ${modeLabel}  ·  Pilotage confirme : ${ptgeLabel}` };
const msgBadgeMode = { payload: modeLabel };
const msgBadgePtge = { payload: ptgeLabel };

return [msgInfoSpe, msgBadgeMode, msgBadgePtge];

/*
 * NOM    : UI_Badge_Urgence
 * TAB    : ui_Accueil_v3
 * ROLE   : Badge d'etat (bandeau) -- reflete msg.urgence, deja pose
 *          par SF_Stabilisation_V1 sur chaque message traversant
 *          Gtion_EtatGlobal_V1.
 * VERSION: 1.0 - 06/08/2026 - Vincent Philippe / Claude
 */
msg.payload = msg.urgence === true ? '🔴 Urgence' : '🟢 OK';
return msg;

/*
 * NOM    : UI_InfoG_COM
 * TAB    : ui_Accueil_v3 (a terme : a migrer vers un flux dedie,
 *          partage entre toutes les pages -- le suivi COM doit se
 *          faire par principe, pas seulement quand cette page est
 *          ouverte. Reste local ici pour cette premiere version.)
 * ROLE   : Bloc InfoG -- suit les messages COM (error/warn/info), commun
 *          a toutes les pages hors admin. Ne reagit qu'aux trames
 *          var=COM -- ignore tout le reste du trafic qui traverse
 *          aussi EtatGlobal_IN.
 * VERSION: 1.0 - 06/08/2026 - Vincent Philippe / Claude
 */
const v = msg.vpiv;
if (!v || v.var !== 'COM') {
    return null;
}
const icones = { error: '🔴', warn: '🟠', info: 'ℹ️' };
const icone = icones[v.prop] || 'ℹ️';
msg.payload = `${icone} ${v.val}`;
return msg;

msg.vpiv = { cat: 'V', var: 'Urg', prop: 'clear', inst: '*', val: 1 };
msg.origine = 'UI';
return msg;

msg.source = "UI"; msg.eventType = "INTENT";
msg.intent = { domain: "CONFIG", target: "modeRZ", action: "SET", value: 1 };
delete msg.vpiv;
return msg;

global.set('RZ_STT', { context: { '*': 'Inactif', _last: 'Inactif' } });
msg.vpiv = { cat: 'V', var: 'CfgS', prop: 'modeRZ', inst: '*', val: '2' };
msg.origine = 'STT';
return msg;

// =============================================================================
// FUNCTION NODE : fn_parse_vpiv_v3
// SORTIES : 3
//   1 — CAT=F  : alimentation globaux uniquement
//   2 — Autres : EVT_RAW_IN → Gtion_EtatGlobal_V1
//   3 — STT + Voice : Switch node → fn_stt_intent_router ou M_Pil_Voice
// =============================================================================

const payload = (msg.payload || '').trim();

// ── 1. Parser la trame VPIV ──────────────────────────────────────────────────
const match = payload.match(/^\$([VIFEA]):([^:]+):([^:]+):([^:]+):(.+)#$/);

if (!match) {
    node.warn('[Bus] Trame non-VPIV ignorée : ' + payload.substring(0, 60));
    return [null, null, null];
}

const [, cat, varName, prop, inst, val] = match;

// ── 2. Alimentation contexte global (toutes trames) ──────────────────────────
// Tentative parse JSON (tableaux type [120,-45,300])
let parsedVal = val;
try { parsedVal = JSON.parse(val); } catch (e) { parsedVal = val; }

const globalKey = 'RZ_' + varName;
const gData = global.get(globalKey) || {};
if (!gData[prop]) gData[prop] = {};
if (inst !== '*') gData[prop][inst] = parsedVal;  // par instance si nommée
gData[prop]['_last'] = parsedVal;                  // toujours : dernière valeur
global.set(globalKey, gData);

// ── 3. Enrichir msg pour les nœuds aval ──────────────────────────────────────
// msg.vpiv permet au Switch sortie 3 de discriminer sans re-parser
msg.vpiv = { cat, var: varName, prop, inst, val: parsedVal };

// ── 4. Routage ────────────────────────────────────────────────────────────────

// CAT=F → sortie 1 uniquement (globaux alimentés ci-dessus, aucun flow aval)
if (cat === 'F') {
    return [msg, null, null];
}

// STT ou Voice → sortie 3 (Switch discriminera ensuite)
if (varName === 'STT' || varName === 'Voice') {
    return [null, null, msg];
}

// Tous les autres (I/V/E/A) → sortie 2 → EVT_RAW_IN → Gtion_EtatGlobal_V1
return [null, msg, null];

/*
 * NOM      : fn_encoder_router_v3 — Encodeur VPIV + routeur hardware
 * CHEMIN   : Node-RED SP → tab RZ_GestionFlux_V3
 * OBJECTIF : Construire la trame VPIV finale et publier vers le ou les
 *            topic(s) MQTT de destination (SE/commande et/ou SE/arduino),
 *            en suivant Table A comme unique source normative de routage.
 *
 * ARTICULATION :
 *   Entrée  : link_in_cmd_brain_v3 (CMD_FROM_BRAIN) ← Gtion_EtatGlobal_V1
 *   Sortie  : mqtt_out_hardware_v3 → SE/commande et/ou SE/arduino
 *             (un seul nœud MQTT OUT ; msg.topic pilote la destination)
 *
 * FORMAT D'ENTRÉE ATTENDU (msg.vpiv) :
 *   { cat, var, prop, inst, val }
 *   Ou msg.payload = trame VPIV brute déjà construite ($CAT:VAR:PROP:INST:VAL#)
 *
 * ROUTAGE HARDWARE — vérifié ligne par ligne sur TableA_updatedV3.csv ET
 * TableAVarSyntheseV21.csv (lignes SOURCE=P uniquement — ce que SP émet),
 * les deux versions concordent parfaitement (aucun conflit) :
 *   - Toutes les VAR sauf CfgS sont mono-cible : toutes leurs propriétés
 *     vont au même endroit (SE ou Arduino) → table VARS_SE / VARS_ARDUINO.
 *   - CfgS est la SEULE VAR "mixte" (property par property) → table
 *     ROUTAGE_SPECIAL ci-dessous.
 *   - Urg.clear est double-cible (SE + Arduino) alors que le reste de
 *     Urg (statut/niveau/source/etat) n'a aucune commande sortante SP.
 *
 * PRÉCAUTIONS :
 *   - Ne router que CAT=V et CAT=A vers le hardware (garde-fou contre la
 *     boucle de rétroaction ACK — cf. synthese_nodeRED_SP.html §3).
 *   - Clé du nom de variable : `var` (pas `varG`) — cohérent avec le reste
 *     du tab (switch "Séparation STT Voice", fn_stt_intent_router).
 *   - Pour une propriété double-cible : DEUX messages distincts sont émis
 *     (même payload, topic différent, msg cloné pour éviter tout partage
 *     de référence). Un seul nœud MQTT OUT suffit, pas de changement de
 *     câblage nécessaire.
 *
 * CORRECTIFS :
 *   (03/07/2026) clé `varG` orpheline → remplacée par `var`.
 *   (04/07/2026) routage par VAR entière → routage par VAR+PROP pour
 *     CfgS et Urg.clear, avec publication double quand Table A l'exige.
 *
 * VERSION : 3.2 - 04/07/2026 - Vincent Philippe (correctif Claude)
 */

// --- Routage par défaut : une VAR entière = une seule cible ---
const VARS_SE = new Set([
    'Sys', 'Gyro', 'Mag', 'CamSE', 'TorchSE',
    'MicroSE', 'STT', 'Voice', 'Appli'
    // CfgS retiré volontairement : géré via ROUTAGE_SPECIAL ci-dessous
]);

const VARS_ARDUINO = new Set([
    'Mtr', 'Odom', 'US', 'SecMvt', 'Lring', 'Lrub',
    'Srv', 'IRmvt', 'FS', 'Ctrl_L', 'Mic'
]);

// --- Exceptions PAR PROPRIÉTÉ (Table A, lignes SOURCE=P) ---
// clé "VAR.PROP" -> liste des cibles ('SE' et/ou 'ARDUINO')
const ROUTAGE_SPECIAL = {
    'CfgS.modeRZ': ['SE', 'ARDUINO'],
    'CfgS.reset': ['SE', 'ARDUINO'],
    'CfgS.typePtge': ['SE', 'ARDUINO'],
    'CfgS.emg': ['ARDUINO'],
    'CfgS.typeReseau': ['SE'],
    'Urg.clear': ['SE', 'ARDUINO']
};

const TOPIC_PAR_CIBLE = { SE: 'SE/commande', ARDUINO: 'SE/arduino' };

// Ne router que V et A vers le hardware (garde-fou anti-boucle ACK)
if (!msg.vpiv || !['V', 'A'].includes(msg.vpiv.cat)) {
    return null;
}

let trame;
const v = msg.vpiv;

if (v && v.var && v.prop) {
    // Construire la trame depuis msg.vpiv
    let valStr;
    if (Array.isArray(v.val)) {
        // Tableau -> CSV (comma-separated values) si tout numérique, JSON sinon
        const allNum = v.val.every(x => typeof x === 'number');
        valStr = allNum ? v.val.join(',') : JSON.stringify(v.val);
    } else if (typeof v.val === 'object' && v.val !== null) {
        valStr = JSON.stringify(v.val);
    } else if (typeof v.val === 'boolean') {
        valStr = v.val ? '1' : '0';
    } else {
        valStr = String(v.val);
    }
    trame = `$${v.cat}:${v.var}:${v.prop}:${v.inst || '*'}:${valStr}#`;

} else if (typeof msg.payload === 'string' &&
    msg.payload.startsWith('$') &&
    msg.payload.endsWith('#')) {
    // Trame déjà construite (cas de certains injects de test)
    trame = msg.payload;
    const parts = trame.slice(1, -1).split(':');
    if (parts.length >= 3) {
        if (!v) msg.vpiv = {};
        msg.vpiv.var = parts[1];
        msg.vpiv.prop = parts[2];   // nécessaire pour ROUTAGE_SPECIAL plus bas
    }
} else {
    node.warn('EncodeurRouter : entrée invalide — ni msg.vpiv ni trame brute');
    return null;
}

msg.payload = trame;

// --- Détermination de la ou des cible(s) ---
const varName = (msg.vpiv && msg.vpiv.var) || '';
const propName = (msg.vpiv && msg.vpiv.prop) || '';
const cle = `${varName}.${propName}`;

let cibles;
if (ROUTAGE_SPECIAL[cle]) {
    cibles = ROUTAGE_SPECIAL[cle];               // cas particulier Table A
} else if (VARS_SE.has(varName)) {
    cibles = ['SE'];
} else if (VARS_ARDUINO.has(varName)) {
    cibles = ['ARDUINO'];
} else {
    node.warn('EncodeurRouter : VAR inconnue : ' + varName + ' → SE/commande par défaut');
    cibles = ['SE'];
}

// Une seule cible : message inchangé, un seul topic.
if (cibles.length === 1) {
    msg.topic = TOPIC_PAR_CIBLE[cibles[0]];
    return msg;
}

// Plusieurs cibles : on clone le message pour chaque topic (RED.util.cloneMessage
// évite de partager la même référence msg entre les deux publications).
const messages = cibles.map(cible => {
    const m = RED.util.cloneMessage(msg);
    m.topic = TOPIC_PAR_CIBLE[cible];
    return m;
});
return [messages];

/*
 * =========================================================================
 * NOM       : fn_stt_intent_router
 * FLOW      : M_Pil_Vocale — branché sur la sortie "STT" du switch
 *             "Séparation STT Voice"
 * CHEMIN    : Node-RED SP → onglet RZ_GestionFlux_V3
 *
 * OBJECTIF
 * --------
 *   Décoder les trames STT.intent (commandes vocales encapsulées par SE) et
 *   produire un msg.vpiv exploitable par Gtion_EtatGlobal_V2, avec un
 *   marqueur
 *   d'origine explicite pour que SF_ValidationIntent_V1 sache qu'il s'agit
 *   d'une intention utilisateur vocale et non d'une donnée de capteur.
 *
 * SORTIES : 3 (inchangées depuis la v1.3)
 *   1 — Intent décodé (msg.vpiv) → link out → EVT_RAW_IN →
 *   Gtion_EtatGlobal_V2
 *   2 — ACK STT (modeSTT, context) → fn_stt_status_store
 *   3 — msg.ack → instance de SF_EmissionACK
 *
 * ENTRÉE
 *   msg.vpiv = { cat, var:"STT", prop, inst, val }, rempli par
 *   fn_parse_vpiv_v3
 *
 *   Deux formes de capsule arrivent dans vpiv.val, entre accolades :
 *     5 champs — cat:var:prop:inst:val      → déjà résolue par SE, on passe
 *     6 champs — id_traitement:cat:var:prop:inst:valBrute → à résoudre ici
 *   L'id_traitement est en PREMIER pour pouvoir trancher sur le nombre de
 *   champs sans rien réinterpréter (convention posée par
 *   rz_stt_handler.sh).
 *
 * CE QUI CHANGE EN v1.4
 * ---------------------
 *   La liste de couleurs codée en dur disparaît. Les recettes de résolution
 *   viennent désormais de global.RZ_Traitements, chargé au démarrage par
 *   fn_init_traitements (onglet Gtion_Init). Ce nœud ne contient plus que
 *   le MOTEUR d'interprétation ; les recettes sont des données éditables.
 *   Trois types sont compris : "table", "nombre", "table_ou_nombre".
 *   Le comportement de CONV_COULEUR_BASE est identique à la v1.3 — c'est le
 *   témoin qui prouve que la migration n'a rien cassé.
 *
 * ARTICULATION
 * ------------
 *   Amont   : rz_stt_handler.sh v3.1 (SE) émet la capsule et attend un ACK
 *             corrélé par id_requete ; rz_vpiv_parser.sh v2.5 écrit le
 *             fichier de corrélation à la réception de cet ACK.
 *   Registre: global.RZ_Traitements ← fn_init_traitements
 *   Aval    : Gtion_EtatGlobal_V2 par la sortie 1, SF_EmissionACK par la 3.
 *
 * PRÉCAUTIONS
 * -----------
 *   - msg.stt_id_requete doit survivre intact jusqu'au bout de la chaîne
 *   pour
 *     que l'ACK final sache à qui répondre. Aucun nœud ne le supprime
 *     aujourd'hui ; vérifier avant d'en ajouter un.
 *   - Si le registre est absent (init non joué), toute capsule à 6 champs
 *     échoue avec la raison registre_absent. C'est volontaire : mieux vaut
 *     un
 *     refus lisible qu'un comportement muet.
 *   - L'id_requete est lu sur l'enveloppe EXTERNE (vpiv.inst), pas dans le
 *     contenu interne.
 *   - Le signe de l'angle de rotation vient de SE : négatif à gauche,
 *   positif
 *     à droite. SP ne reçoit pas l'identifiant de commande et ne peut donc
 *     pas
 *     déduire le sens. Décision du 18/10/2026.
 *
 * VERSION : 1.4 — 18/10/2026 — Vincent Philippe / Claude
 *           1.4 : registre externalisé dans global.RZ_Traitements, moteur
 *                 d'interprétation générique à trois types
 *           1.3 : première résolution réelle (CONV_COULEUR_BASE en dur)
 *           1.2 : capsule à 6 champs reconnue, id_requete lu sur
 *           l'enveloppe
 *           1.1 : migration msg.command → msg.vpiv + msg.origine
 * =========================================================================
 */

const vpiv = msg.vpiv;

if (!vpiv || vpiv.var !== 'STT') {
    node.warn('[STT Router] msg.vpiv absent ou VAR incorrect');
    return [null, null, null];
}

// ───────────────────────────────────────────────────────────────────────
// SECTION 1 — ACK de statut STT : sortie 2 (inchangé)
// ───────────────────────────────────────────────────────────────────────
if (vpiv.prop === 'modeSTT' || vpiv.prop === 'context') {
    msg.stt_status = {
        prop: vpiv.prop, val: vpiv.val, timestamp: Date.now()
    };
    node.log('[STT Router] ACK ' + vpiv.prop + '=' + vpiv.val);
    return [null, msg, null];
}

if (vpiv.prop !== 'intent') {
    node.warn('[STT Router] PROP inconnue ignorée : ' + vpiv.prop);
    return [null, null, null];
}

// id_requete : porté par INST de l'enveloppe externe, pas par le contenu.
const id_requete = vpiv.inst;

const innerRaw = String(vpiv.val).replace(/^\{|\}$/g, '').trim();
const parts = innerRaw.split(':');

// ───────────────────────────────────────────────────────────────────────
// SECTION 2 — Capsule à 5 champs : SE a déjà résolu, on ne touche à rien
// ───────────────────────────────────────────────────────────────────────
if (parts.length === 5) {
    const [iCat, iVar, iProp, iInst, iVal] = parts;

    if (!['V', 'I', 'A'].includes(iCat)) {
        node.warn('[STT Router] CAT interne refusée : ' + iCat);
        return [null, null, null];
    }

    msg.vpiv = {
        cat: iCat, var: iVar, prop: iProp, inst: iInst, val: iVal
    };
    msg.origine = 'STT';
    msg.topic = 'stt_intent';

    node.log('[STT Router] Intent (résolu SE) → ' + iCat + ':' + iVar + ':'
        + iProp + ':' + iInst + ':' + iVal);

    return [msg, null, null];
}

// ───────────────────────────────────────────────────────────────────────
// SECTION 3 — MOTEUR D'INTERPRÉTATION
//
// Prend une recette du registre et la valeur brute captée au micro, rend
// soit
// la valeur VPIV finale, soit une raison d'échec. Aucune recette n'est
// écrite
// ici : ce sont des données, elles vivent dans global.RZ_Traitements.
// ───────────────────────────────────────────────────────────────────────
function appliquerGabarit(recette, valeur) {
    // Sans gabarit, la valeur part telle quelle (cas Srv.angle,
    // Lring.lumin).
    if (!recette.gabarit) { return String(valeur); }

    // Avec gabarit, {valeur} reçoit le nombre lu et les autres jetons les
    // constantes déclarées à côté. Exemple : "{vitesse},{valeur},{acc}".
    return recette.gabarit.replace(/\{(\w+)\}/g, (_, jeton) => {
        if (jeton === 'valeur') { return String(valeur); }
        const c = (recette.constantes || {})[jeton];
        return c === undefined ? '' : String(c);
    });
}

function lireDansTable(recette, valBrute) {
    const cle = String(valBrute).trim().toLowerCase();
    const v = recette.table ? recette.table[cle] : undefined;
    return v === undefined ? null : v;
}

function lireNombre(recette, valBrute) {
    const n = recette.nombre || {};
    const brut = String(valBrute).trim();

    // Rien de capté : on retombe sur le défaut de la recette s'il existe.
    if (brut === '' && n.defaut !== undefined) { return n.defaut; }

    // parseFloat et non Number : tolère « 90 degrés » en ne lisant que 90.
    // Le signe éventuel vient de SE (négatif = gauche) et doit être
    // conservé.
    const x = parseFloat(brut.replace(',', '.'));
    if (!isFinite(x)) { return null; }

    const y = (n.entier === false) ? x : Math.round(x);
    if (n.min !== undefined && y < n.min) { return null; }
    if (n.max !== undefined && y > n.max) { return null; }
    return y;
}

function resoudre(recette, valBrute) {
    if (recette.actif === false) {
        return { ok: false, raison: recette.erreur || 'recette_inactive' };
    }

    let valeur = null;

    if (recette.type === 'table') {
        valeur = lireDansTable(recette, valBrute);

    } else if (recette.type === 'nombre') {
        valeur = lireNombre(recette, valBrute);

    } else if (recette.type === 'table_ou_nombre') {
        // L'adverbe d'abord (« fort », « doux »), le nombre sinon.
        valeur = lireDansTable(recette, valBrute);
        if (valeur === null) { valeur = lireNombre(recette, valBrute); }

    } else {
        return { ok: false, raison: 'type_de_recette_inconnu' };
    }

    if (valeur === null) {
        return { ok: false, raison: recette.erreur || 'valeur_invalide' };
    }
    return { ok: true, valeur: appliquerGabarit(recette, valeur) };
}

// ───────────────────────────────────────────────────────────────────────
// SECTION 4 — Capsule à 6 champs : résolution côté SP
// ───────────────────────────────────────────────────────────────────────
if (parts.length === 6) {
    const [id_traitement, iCat, iVar, iProp, iInst, valBrute] = parts;

    const registre = global.get('RZ_Traitements');

    // Le registre manque : l'init n'a pas été joué. On le dit clairement
    // plutôt que de laisser croire à une commande mal prononcée.
    if (!registre) {
        node.error('[STT Router] global.RZ_Traitements absent — '
            + 'fn_init_traitements n\'a pas ete joue. Capsule refusee '
            + '(id_requete=' + id_requete + ')');
        msg.ack = {
            var: 'STT', prop: 'intent', id_requete,
            statut: 'FAIL', raison: 'registre_absent'
        };
        return [null, null, msg];
    }

    const recette = registre[id_traitement];

    if (!recette) {
        node.warn('[STT Router] id_traitement inconnu du registre : '
            + id_traitement + ' (id_requete=' + id_requete + ')');
        msg.ack = {
            var: 'STT', prop: 'intent', id_requete,
            statut: 'FAIL', raison: 'resolution_non_implementee'
        };
        return [null, null, msg];
    }

    const res = resoudre(recette, valBrute);

    if (!res.ok) {
        node.warn('[STT Router] ' + id_traitement + ' : echec « '
            + res.raison + ' » sur la valeur captee « ' + valBrute + ' »');
        msg.ack = {
            var: 'STT', prop: 'intent', id_requete,
            statut: 'FAIL', raison: res.raison
        };
        return [null, null, msg];
    }

    msg.vpiv = {
        cat: iCat, var: iVar, prop: iProp, inst: iInst, val: res.valeur
    };
    msg.origine = 'STT';
    msg.topic = 'stt_intent';
    msg.stt_id_requete = id_requete;

    node.log('[STT Router] Intent résolu (' + id_traitement + ') → '
        + iVar + '.' + iProp + '=' + res.valeur
        + ' (mot capté: ' + valBrute + ')');

    return [msg, null, null];
}

// ───────────────────────────────────────────────────────────────────────
// SECTION 5 — Capsule mal formée
// ───────────────────────────────────────────────────────────────────────
node.warn('[STT Router] Intent mal formé — 5 ou 6 champs attendus, reçu '
    + parts.length + ' : ' + innerRaw);
return [null, null, null];

// =============================================================================
// FUNCTION NODE : fn_stt_status_store
// FLOW          : M_Pil_Vocale
// BRANCHÉ SUR   : fn_stt_intent_router sortie 2
//
// OBJECTIF
// --------
// Stocker l'état STT courant (modeSTT + context) dans le contexte flow.
// Source de vérité locale pour ui_STT quand il sera créé.
// Pas de logique décisionnelle — stockage uniquement.
//
// ENTRÉE : msg.stt_status = { prop, val, timestamp }
//   prop = 'modeSTT' → val = 'KWS' | 'OFF'
//   prop = 'context' → val = 'Cmde' | 'Conv' | 'Mixte' | 'Inactif'
// =============================================================================

const s = msg.stt_status;

if (!s || !s.prop) {
    node.warn('[STT Status] msg.stt_status absent');
    return null;
}

// Lire l'état courant (ou initialiser)
const sttState = flow.get('stt_state') || {
    modeSTT:   'OFF',
    context:   'Inactif',
    updatedAt: null
};

// Mettre à jour le champ concerné
sttState[s.prop]    = s.val;
sttState.updatedAt  = s.timestamp;
flow.set('stt_state', sttState);

node.log('[STT Status] ' + s.prop + '=' + s.val);

// Transmettre pour debug ou futur ui_STT
// (brancher un nœud debug ici pendant les tests)
msg.payload = sttState;
return msg;

// =============================================================================
// FUNCTION NODE : fn_voice_status_store
// FLOW          : M_Pil_Voice
// BRANCHÉ SUR   : Switch sortie 3 de fn_parse_vpiv_v3, branche "Voice"
//
// OBJECTIF
// --------
// Stocker l'état Voice courant (vol + output) dans le contexte flow.
// Source de vérité locale pour ui_Voice quand il sera créé.
// Pas de logique décisionnelle — stockage uniquement.
//
// ENTRÉE : msg.vpiv = { cat, var:"Voice", prop, inst, val }
//   prop = 'vol'    → val = 0-100 (normalisé VPIV)
//   prop = 'output' → val = 'internal' | 'jack' | 'bt'
// =============================================================================

const vpiv = msg.vpiv;

if (!vpiv || vpiv.var !== 'Voice') {
    node.warn('[Voice Status] msg.vpiv absent ou VAR incorrect');
    return null;
}

// Lire l'état courant (ou initialiser)
const voiceState = flow.get('voice_state') || {
    vol:       80,
    output:    'internal',
    updatedAt: null
};

// Mettre à jour le champ concerné
// vol et output sont les deux seuls ACKs Voice remontant de SE
if (vpiv.prop === 'vol' || vpiv.prop === 'output') {
    voiceState[vpiv.prop] = vpiv.val;
    voiceState.updatedAt  = Date.now();
    flow.set('voice_state', voiceState);
    node.log('[Voice Status] ' + vpiv.prop + '=' + vpiv.val);
} else {
    node.warn('[Voice Status] PROP inconnue ignorée : ' + vpiv.prop);
    return null;
}

// Transmettre pour debug ou futur ui_Voice
msg.payload = voiceState;
return msg;

/*
 * Encodeur VPIV + routeur hardware
 * ---------------------------------
 * Chemin     : RZ_GestionFlux_V3 - Node-RED SP
 * Objectif   : Construire la trame VPIV finale et choisir
 *              le topic MQTT de destination
 *
 * Entrée (msg.vpiv) :
 *   { cat, varG, prop, inst, val }
 *   Ou msg.payload = trame VPIV brute déjà construite
 *
 * Routage hardware (Table A / doc_A1) :
 *   Variables SE  → topic SE/commande
 *   Variables A   → topic SE/arduino  (via mqtt_bridge.py)
 *
 * Variables SE (Table A, DIRECTION contient SP→SE) :
 *   CfgS, Sys, Gyro, Mag, CamSE, TorchSE, MicroSE,
 *   STT, Voice, Appli, Urg
 *
 * Variables Arduino (Table A, DIRECTION contient SP→A) :
 *   Mtr, Odom, US, SecMvt, Lring, Lrub, Srv,
 *   IRmvt, FS, Ctrl_L, Mic
 *
 * Format trame produite : $CAT:VAR:PROP:INST:VAL#
 *
 * Version : 3.0 - 2026-04-27 - Vincent Philippe
 */

// Variables destinées au SE (SP→SE dans Table A)
const VARS_SE = new Set([
    'CfgS', 'Sys', 'Gyro', 'Mag', 'CamSE', 'TorchSE',
    'MicroSE', 'STT', 'Voice', 'Appli', 'Urg', 'COM'
]);

// Variables destinées à l'Arduino via bridge SE (SP→A dans Table A)
const VARS_ARDUINO = new Set([
    'Mtr', 'Odom', 'US', 'SecMvt', 'Lring', 'Lrub',
    'Srv', 'IRmvt', 'FS', 'Ctrl_L', 'Mic'
]);

// Ne router que V et A vers le hardware
if (!msg.vpiv || !['V', 'A'].includes(msg.vpiv.cat)) {
    return null;
}

let trame;
const v = msg.vpiv;

if (v && v.varG && v.prop) {
    // Construire la trame depuis msg.vpiv
    let valStr;
    if (Array.isArray(v.val)) {
        // Tableau → JSON si mixte, CSV si tout numérique
        const allNum = v.val.every(x => typeof x === 'number');
        valStr = allNum ? v.val.join(',') : JSON.stringify(v.val);
    } else if (typeof v.val === 'object' && v.val !== null) {
        valStr = JSON.stringify(v.val);
    } else if (typeof v.val === 'boolean') {
        valStr = v.val ? '1' : '0';
    } else {
        valStr = String(v.val);
    }
    trame = `$${v.cat}:${v.varG}:${v.prop}:${v.inst || '*'}:${valStr}#`;

} else if (typeof msg.payload === 'string' &&
           msg.payload.startsWith('$') &&
           msg.payload.endsWith('#')) {
    // Trame déjà construite
    trame = msg.payload;

    // Extraire varG pour le routage
    const parts = trame.slice(1,-1).split(':');
    if (parts.length >= 2) {
        if (!v) msg.vpiv = {};
        msg.vpiv.varG = parts[1];
    }
} else {
    node.warn('EncodeurRouter : entrée invalide — ni msg.vpiv ni trame brute');
    return null;
}

msg.payload = trame;

// --- Routage topic MQTT ---
const varName = (msg.vpiv && msg.vpiv.varG) || '';

if (VARS_SE.has(varName)) {
    msg.topic = 'SE/commande';
} else if (VARS_ARDUINO.has(varName)) {
    msg.topic = 'SE/arduino';
} else {
    // VAR inconnue : avertissement + défaut SE/commande
    node.warn('EncodeurRouter : VAR inconnue : ' + varName + ' → SE/commande par défaut');
    msg.topic = 'SE/commande';
}

return msg;

// Prépare msg.vpiv depuis msg.payload (pour les tests inject)
msg.vpiv = msg.payload;
return msg;

const rzCfgS = global.get('RZ_CfgS') || {};
function lireCfgS(prop) {
    const p = rzCfgS[prop];
    if (!p) return undefined;
    return p._last !== undefined ? p._last : p['*'];
}
msg.payload = { modeRZ: lireCfgS('modeRZ'), typePtge: lireCfgS('typePtge') };
return msg;

// Récupération des données globales
let enrichedVars = global.get("enrichedVars") || {}; 
let tableauPourUI = [];

// On réinitialise la sélection à chaque rafraîchissement de liste
flow.set("varSelected", ""); 

// Parcours de toutes les variables du fichier globalSave
Object.entries(enrichedVars).forEach(([nomVarG, e]) => {
    if (!nomVarG || !e || typeof e !== "object") return;

    // On prépare un résumé des propriétés pour l'affichage tableau
    let props = e.proprietes || [];
    let proprieteResume = props.length > 0 ? props.map(p => p.nomP).join(", ") : "";

    // On pousse l'objet complet vers le tableau UI
    tableauPourUI.push({
        nomVarG: nomVarG,
        instances: (e.instances || ["*"]).join(", "),
        proprietes: proprieteResume,
        descriptionVarG: e.descriptionVarG || "", // On garde le champ description
        dateUpdateVarG: e.dateUpdateVarG || ""    // On garde la date
    });
});

msg.payload = tableauPourUI;
return msg;

// =================================================================
// 🔹 InfosSauvegardeVars
// - Enregistre les modifs de la variable globale
// - Gère le renommage de la clé dans l'objet global
// =================================================================

const nodeFs = global.get('nodeFs');
const filePath = global.get("rzPath");

let enrichedVars = global.get("enrichedVars") || {};
let varSelected = flow.get("varSelected");
let formData = msg.payload;

if (!formData || !formData.nomVarG) return null;

let newName = formData.nomVarG.trim();
let oldName = (varSelected === "new") ? null : varSelected;

if (!oldName || !enrichedVars[oldName]) {
    // CRÉATION : Nouvel objet
    enrichedVars[newName] = {
        nomVarG: newName,
        nomCpletVarG: formData.nomCpletVarG || "",
        instances: formData.instances ? formData.instances.split(",").map(e => e.trim()) : ["*"],
        descriptionVarG: formData.descriptionVarG || "",
        dateUpdateVarG: new Date().toISOString(),
        proprietes: []
    };
} else {
    // MODIFICATION : On récupère l'existant pour ne rien écraser (les P notamment)
    let data = enrichedVars[oldName];

    if (oldName !== newName) {
        enrichedVars[newName] = data; // On déplace les données
        delete enrichedVars[oldName]; // On supprime l'ancienne clé
    }

    // Mise à jour des champs modifiables
    enrichedVars[newName].nomVarG = newName;
    enrichedVars[newName].nomCpletVarG = formData.nomCpletVarG;
    enrichedVars[newName].instances = formData.instances.split(",").map(e => e.trim());
    enrichedVars[newName].descriptionVarG = formData.descriptionVarG;
    enrichedVars[newName].dateUpdateVarG = new Date().toISOString();
}

// Persistence
global.set("enrichedVars", enrichedVars);
try {
    const toSave = { enrichedVars: enrichedVars, lastUpdate: new Date().toISOString() };
    nodeFs.writeFileSync(filePath, JSON.stringify(toSave, null, 4), 'utf8');
} catch (err) { node.error(err); }

flow.set("varSelected", newName);
msg.payload = newName;
return msg;

// 🔹 recupVarSelected
// - Détermine si on sélectionne une variable existante ou si on crée une nouvelle
// - Met à jour flow.varSelected
// - Fournit msg.info et msg.payload adaptés

let enrichedVars = global.get("enrichedVars") || {};
let listeVars = Object.keys(enrichedVars);
let varSelected = null;

// 1) Cas bouton "Ajouter une VarG"
if (msg.topic === "newVarG") {
    varSelected = "new";
}
// 2) Cas sélection dans la table
else {
    varSelected = msg.payload?.row?.nomVarG || msg.payload?.nomVarG || null;
}

// 3) Vérification : aucune sélection
if (!varSelected) {
    msg.info = (listeVars.length === 0)
        ? "⚠️ Aucune variable existante dans enrichedVars."
        : "⚠️ Aucune variable sélectionnée pour édition.";
    return msg;  // on sort proprement
}

// 4) Stockage de la sélection
flow.set("varSelected", varSelected);

// 5) Message d'info
msg.info = (varSelected === "new")
    ? "➕ Création d'une nouvelle variable."
    : `✅ Vous êtes sur la variable : ${varSelected}`;

// 6) Retour
msg.payload = varSelected;
return msg;

// =================================================================
// 🔹 prepareFormVarSelected
// - Prépare le formulaire Form_Var_Modif selon varSelected
// - Gère : création nouvelle variable, édition variable existante
// =================================================================

let enrichedVars = global.get("enrichedVars") || {};
let varSelected = flow.get("varSelected") || null;

// 1) Cas création d'une nouvelle variable
if (varSelected === "new") {
    msg.payload = {
        nomVarG: "",
        nomCpletVarG: "", // Gardé pour compatibilité
        instances: "*", 
        descriptionVarG: "- Objectif(s): \n- Origine: \n- Autres : ",
        dateUpdateVarG: new Date().toISOString()
    };
    msg.topic = "newVarG";
    return msg;
}

// 2) Cas édition d'une variable existante
if (varSelected && enrichedVars[varSelected]) {
    const selected = enrichedVars[varSelected];
    msg.payload = {
        nomVarG: selected.nomVarG || varSelected,
        nomCpletVarG: selected.nomCpletVarG || "", // On ne supprime rien
        instances: selected.instances ? selected.instances.join(", ") : "*",
        descriptionVarG: selected.descriptionVarG || "",
        dateUpdateVarG: selected.dateUpdateVarG || new Date().toISOString()
    };
    return msg;
}

// 3) Cas par défaut / Sécurité
msg.payload = {
    nomVarG: "",
    nomCpletVarG: "",
    instances: "",
    descriptionVarG: "",
    dateUpdateVarG: new Date().toISOString()
};
return msg;

const nodeFs = global.get('nodeFs');
const filePath = global.get("rzFilePath");

if (msg.payload === "confirm_clicked") {
    const varToDelete = flow.get("pendingDeletion");
    let enrichedVars = global.get("enrichedVars") || {};

    if (varToDelete && enrichedVars[varToDelete]) {
        // 1. Suppression RAM
        delete enrichedVars[varToDelete];
        global.set("enrichedVars", enrichedVars);

        // 2. Persistance Disque immédiate
        try {
            if (Object.keys(enrichedVars).length === 0) {
                // Optionnel : protéger si on veut interdire de supprimer la DERNIÈRE variable
                // ou simplement autoriser un fichier vide :
                nodeFs.writeFileSync(filePath, JSON.stringify({ enrichedVars: {}, lastUpdate: new Date().toISOString() }, null, 4));
            } else {
                nodeFs.writeFileSync(filePath, JSON.stringify({ enrichedVars: enrichedVars, lastUpdate: new Date().toISOString() }, null, 4));
            }
            node.warn(`🗑️ Variable ${varToDelete} supprimée (RAM & Disque)`);
        } catch (err) {
            node.error("❌ Erreur lors de la suppression disque : " + err.message);
        }
    }

    flow.set("varSelected", null);
    msg.payload = "refresh";
    return msg;
}
return null;

// open-dialog -> Preparation d'une Boite de Dialogue Suppression
// les actions dans ui-notification doivent être configuré selon un schéma précis
const varSelected = flow.get("varSelected") || null;

if (!varSelected || varSelected === "none" || varSelected === "new") {
    msg.payload = {
        type: "warning", 
        title: "Aucune variable",
        text: "Veuillez sélectionner une variable à supprimer.",
        duration: 3000
    };
    return msg;
}

flow.set("pendingDeletion", varSelected);
// gestion dynamique du ui-notification, les mots clefs de ui-update sont spécifique au noeud
msg.payload = {
    type: "warning",
    title: "Confirmation suppression",
    text: `Voulez-vous vraiment supprimer la variable "<strong>${varSelected}</strong>" ?`,
    displayTime: 0, // Ne pas fermer automatiquement
    ui_update: {
        allowConfirm: true,
        allowDismiss: true,
        confirmText: "✅ Supprimer",
        dismissText: "❌ Annuler"
    }
};

return msg;

/*******************************************************************************
 * NOM DU NŒUD : chargeEnrichedVarsToMemory
 * RÔLE : Charger le dictionnaire maître en RAM au lancement de l'UI
 * DERNIÈRE MODIF : 24/03/2026 - Cohérence SF_Init_1 / nodeFs
 ******************************************************************************/

// --- CONFIGURATION ---
const nodeFs = global.get('nodeFs');
const filePath = global.get("rzPath");

// --- FONCTIONS DE COHÉRENCE (Identiques à SF_Init_1) ---
function defaultForType(type) {
    switch (type) {
        case "boolean": return false;
        case "int": case "number": return 0;
        case "array": return [];
        case "object": return {};
        default: return "";
    }
}

// 1. TENTATIVE DE RÉCUPÉRATION RAM
let enrichedVars = global.get("enrichedVars");

// 2. SI RAM VIDE : LECTURE PHYSIQUE DU FICHIER (nodeFs)
if (!enrichedVars || Object.keys(enrichedVars).length === 0) {
    try {
        if (nodeFs.existsSync(filePath)) {
            const rawData = nodeFs.readFileSync(filePath, 'utf8');
            const parsed = JSON.parse(rawData);
            enrichedVars = parsed.enrichedVars || {};

            // On peuple la RAM pour que le reste de l'UI fonctionne immédiatement
            global.set("enrichedVars", enrichedVars);
            node.status({ fill: "blue", shape: "dot", text: "Chargé depuis Disque" });
        } else {
            node.error("🚨 CRITIQUE : globalSave.json introuvable !");
            node.status({ fill: "red", shape: "ring", text: "Fichier absent" });
            return null;
        }
    } catch (e) {
        node.error("🚨 Erreur de lecture : " + e.message);
        return null;
    }
} else {
    node.status({ fill: "green", shape: "dot", text: "Données RAM prêtes" });
}

// 3. TRANSFERT VERS LE FLOW UI
msg.payload = enrichedVars;
return msg;

info:
// Les variables sont stockées dans deux types de stockage : "default" et "file".
// Ce nœud synchronise les variables globales avec enrichedVars.
// Il met à jour enrichedVars avec les variables globales actuelles
// et s'assure que chaque variable suit la nouvelle structure définie.

// Les variables sont structurées avec des propriétés comme nomVarG, instances, propriétés, etc.
// La fonction gère également la restauration des variables globales manquantes depuis enrichedVars.
// Elle prend en compte les instances et les sous-variables pour une synchronisation cohérente.

func:
// =================================================================
// 🔹 routerAction (SÉCURISÉ ANTI-BOUCLE)
// =================================================================

// 1. ANTI-BOUCLE : Si c'est un message de retour (refresh/save), on stoppe net.
if (msg.topic === "refresh" || msg.topic === "saveBase" || msg.topic === "saveValues") {
    return null;
}

// 2. Extraction des données (cherche à la racine OU dans payload)
let action = msg.action || (msg.payload ? msg.payload.action : null);
let prop = msg.prop || (msg.payload ? msg.payload.prop : null);

// Si aucune intention d'action n'est trouvée, on ne fait rien
if (!action || !prop) return null;

// 3. Mémoire pour le nom original (utile pour SauvResultatActions)
flow.set("propOriginalName", (prop.nomP === 'NouvelleP') ? null : prop.nomP);

// 4. Routage vers les 3 sorties
// --- SORTIE 1 : Base ---
if (action === "base") {
    msg.topic = "openEditor";
    msg.editor = "base";
    msg.prop = (prop._isNew) ? { nomP: "", nomCpletP: "", descriptionP: "", typeP: "string", optionsP: [] } : prop;
    return [msg, null, null];
}

// --- SORTIE 2 : Valeurs ---
if (action === "valeurs") {
    msg.topic = "openEditor"; // FIX BUG 2 : Réveille le v-if du template
    msg.editor = "valeurs";   // FIX BUG 2
    msg.prop = prop;
    msg.instances = flow.get("instances") || ["*"];
    return [null, msg, null];
}

// --- SORTIE 3 : Delete ---
if (action === "delete") {
    msg.topic = "delete";
    msg.prop = prop;
    return [null, null, msg];
}

return null;

// =================================================================
// 🔹 prepareTableauProprietes
// - Prépare l'objet complexe pour le Template_Proprietes
// - REQUIS : msg.payload.instances, .proprietes, .variable
// =================================================================

let varSelected = flow.get("varSelected");
let enrichedVars = global.get("enrichedVars") || {};

// Si aucune sélection, on envoie une structure vide pour éviter les erreurs Vue
if (!varSelected || !enrichedVars[varSelected]) {
    msg.payload = { proprietes: [], instances: ["*"], variable: { nomVarG: "Sélectionnez une VarG" } };
    return msg;
}

let variable = enrichedVars[varSelected];

// --- FIX : PARSING DES INSTANCES ---
let instList = variable.instances || ["*"];

// Si c'est un tableau de 1 élément qui contient des ";", on le découpe
if (Array.isArray(instList) && instList.length === 1 && instList[0].includes(';')) {
    instList = instList[0].split(';').map(s => s.trim()).filter(s => s !== "");
}
// Si jamais c'était resté une simple String
else if (typeof instList === 'string') {
    instList = instList.split(';').map(s => s.trim()).filter(s => s !== "");
}

// On s'assure que "*" est toujours là et en premier
if (!instList.includes("*")) instList.unshift("*");
// -----------------------------------

// 1. On prépare la liste des lignes (P)
let listeP = (variable.proprietes || []).map(p => {
    return {
        nomP: p.nomP,
        nomCpletP: p.nomCpletP || "",
        descriptionP: p.descriptionP || "",
        typeP: p.typeP || "string",
        optionsP: p.optionsP || [],
        valeurs: p.valeurs || {},
        defaut: (p.valeurs && p.valeurs["*"]) !== undefined ? p.valeurs["*"] : "-"
    };
});

// 2. Ajout ligne "NouvelleP"
listeP.push({ nomP: 'NouvelleP', _isNew: true, typeP: 'string' });

// 3. Stockage des instances PROPRES dans le flow
flow.set("instances", instList);

// 4. On construit le payload pour le Template HTML
msg.payload = {
    proprietes: listeP,
    instances: instList, // Ici on envoie le tableau découpé
    variable: { nomVarG: variable.nomVarG }
};

return msg;

// =================================================================
// 🔹 SauvResultatActions (CODE COMPLET)
// =================================================================

const nodeFs = global.get('nodeFs');
const filePath = global.get("rzPath");

let enriched = global.get('enrichedVars') || {};
let varSelected = flow.get('varSelected');
let originalName = flow.get("propOriginalName");

if (!varSelected || !enriched[varSelected]) return null;
let variable = enriched[varSelected];

// --- CAS A : Sauvegarde Structure (Base) ---
if (msg.topic === "saveBase") {
    let p = msg.payload;

    // 1. Mise à jour des instances si présentes (Parsing par virgule ou ;)
    if (msg.instancesInput) {
        let newInst = msg.instancesInput.split(/[ ,;]+/).map(s => s.trim()).filter(s => s !== "");
        if (!newInst.includes("*")) newInst.unshift("*");
        variable.instances = newInst;
    }

    let idx = variable.proprietes.findIndex(pr => pr.nomP === originalName);

    // On conserve les valeurs existantes même si on change la structure
    let oldProp = (idx >= 0) ? variable.proprietes[idx] : { valeurs: {} };

    let updatedProp = {
        nomP: p.nomP,
        nomCpletP: p.nomCpletP || "",
        descriptionP: p.descriptionP || "",
        typeP: p.typeP || "string",
        optionsP: Array.isArray(p.optionsP) ? JSON.parse(JSON.stringify(p.optionsP)) : [],
        valeurs: oldProp.valeurs || { "*": "" }
    };

    // Initialisation des clés manquantes pour les nouvelles instances
    (variable.instances || ["*"]).forEach(i => {
        if (updatedProp.valeurs[i] === undefined) updatedProp.valeurs[i] = "";
    });

    if (idx === -1) {
        variable.proprietes.push(updatedProp);
    } else {
        variable.proprietes[idx] = updatedProp;
    }
}

// --- CAS B : Sauvegarde Valeurs ---
else if (msg.topic === "saveValues") {
    if (msg.prop && msg.prop.nomP) {
        let idx = variable.proprietes.findIndex(pr => pr.nomP === msg.prop.nomP);
        if (idx >= 0) {
            // On écrase le dictionnaire de valeurs avec celui venant de l'éditeur
            variable.proprietes[idx].valeurs = JSON.parse(JSON.stringify(msg.prop.valeurs));
        }
    }
}

// --- CAS C : Suppression ---
else if (msg.topic === "delete") {
    if (msg.prop && msg.prop.nomP) {
