/*
 * parseVPIV
 * ---------
 * Chemin     : flux Diag_SE_Statut - Node-RED SP
 * Objectif   : décoder une trame VPIV $CAT:VAR:PROP:INST:VAL#
 * Entree     : msg.payload = trame brute (string)
 * Sortie     : msg.vpiv = { cat, varAbbr, prop, inst, value }
 *              msg.rawTrame = trame brute pour affichage
 * Format VPIV canonique (Table A corrigée) :
 *   $CAT:VAR:PROP:INST:VAL#  — PROP en position 3, INST en position 4
 * Version : 3.0 - 2026-04-28 - Vincent Philippe
 */

const raw = (msg.payload || '').toString().trim();
msg.rawTrame = raw;

const m = raw.match(/^\$([A-Z]):([^:]+):([^:]+):([^:]+):[\s\S]+?#$/);
if (!m) {
    node.warn('parseVPIV : trame non reconnue : ' + raw);
    msg.vpiv = null;
    return msg;
}

// Décomposition avec slice pour récupérer VAL même si elle contient ':'
const content = raw.slice(1, -1);
const parts   = content.split(':');
const cat     = parts[0];
const varAbbr = parts[1];
const prop    = parts[2];
const inst    = parts[3];
const value   = parts.slice(4).join(':');

msg.vpiv = { cat, varAbbr, prop, inst, value };
msg.payload = msg.vpiv;

return msg;

/*
 * Extraire Sys - v2.0
 * --------------------
 * Chemin     : flux Diag_SE_Statut
 * Objectif   : extraire les métriques système depuis les trames VPIV
 *
 * Format réel SE (rz_sys_monitor.sh v4.0) :
 *   Une trame par métrique, valeur entière, instance = SE
 *   $F:Sys:dataContCpu:SE:42#
 *   $F:Sys:dataContThermal:SE:38#
 *   $F:Sys:dataContStorage:SE:60#
 *   $F:Sys:dataContMem:SE:57#
 *   $F:Sys:dataContBatt:SE:81#   (sens inverse : alerte si < seuil)
 *   $I:Sys:uptime:SE:3600#
 *   $I:Sys:modeSys:SE:FLOW#
 *
 * Utilise flow.get/set pour conserver les valeurs des autres
 * métriques entre chaque trame individuelle.
 *
 * Unités : % direct pour cpu/mem/storage/batt, °C pour thermal
 * Version : 2.0 - 2026-04-28 - Vincent Philippe
 */

const v = msg.vpiv;
if (!v) return null;

const prop = v.prop;
const val  = v.value;

// Filtrage : ne traiter que les propriétés de données continues
const propsDonnees = [
    'dataContCpu', 'dataContMem', 'dataContStorage',
    'dataContBatt', 'dataContThermal',
    'dataMoyCpu',  'dataMoyMem',  'dataMoyStorage',
    'dataMoyBatt', 'dataMoyThermal'
];

if (!propsDonnees.includes(prop)) {
    // Trame Sys non-data (modeSys, paraSys, uptime...) → ignorer
    return null;
}

// Récupérer les valeurs déjà connues depuis le contexte flow
// pour ne pas écraser les autres métriques à chaque trame
msg.sysCpu     = flow.get('sysCpu')     || '-';
msg.sysMem     = flow.get('sysMem')     || '-';
msg.sysStorage = flow.get('sysStorage') || '-';
msg.sysBatt    = flow.get('sysBatt')    || '-';
msg.sysThermal = flow.get('sysThermal') || '-';

// Mise à jour de la métrique concernée par cette trame
switch(prop) {
    case 'dataContCpu':
    case 'dataMoyCpu':
        msg.sysCpu = val;
        flow.set('sysCpu', val);
        break;
    case 'dataContMem':
    case 'dataMoyMem':
        msg.sysMem = val;
        flow.set('sysMem', val);
        break;
    case 'dataContStorage':
    case 'dataMoyStorage':
        msg.sysStorage = val;
        flow.set('sysStorage', val);
        break;
    case 'dataContBatt':
    case 'dataMoyBatt':
        msg.sysBatt = val;
        flow.set('sysBatt', val);
        break;
    case 'dataContThermal':
    case 'dataMoyThermal':
        msg.sysThermal = val;
        flow.set('sysThermal', val);
        break;
}

return msg;

/*
 * Dispatch Sys -> UI
 * ------------------
 * ui-text affiche msg.payload — on envoie 5 messages séparés.
 * Ordre sorties : cpu, mem, storage, batt, thermal
 * Version : 2.0 - 2026-04-28 - Vincent Philippe
 */
const cpu     = String(msg.sysCpu     !== undefined ? msg.sysCpu     : '-');
const mem     = String(msg.sysMem     !== undefined ? msg.sysMem     : '-');
const storage = String(msg.sysStorage !== undefined ? msg.sysStorage : '-');
const batt    = String(msg.sysBatt    !== undefined ? msg.sysBatt    : '-');
const thermal = String(msg.sysThermal !== undefined ? msg.sysThermal : '-');

return [
    { payload: cpu     },
    { payload: mem     },
    { payload: storage },
    { payload: batt    },
    { payload: thermal }
];

/*
 * Extraire Gyro - v2.0
 * ---------------------
 * Chemin     : flux Diag_SE_Statut
 * Objectif   : extraire les axes Gx Gy Gz depuis la trame VPIV
 *
 * Formats supportés (robustesse) :
 *   Objet  {x:120,y:-45,z:300}  ← format officiel SE v3
 *   Tableau [120,-45,300]        ← format legacy / test
 *
 * Filtrage : seules dataContGyro et dataMoyGyro sont traitées.
 * Unités : valeurs brutes = rad/s × 100
 *          Affichage = divisé par 100 → rad/s réel
 * Version : 2.0 - 2026-04-28 - Vincent Philippe
 */

const v = msg.vpiv;
if (!v) return null;

// Filtrer : ne traiter que les props de données
const propsGyro = ['dataContGyro', 'dataMoyGyro'];
if (!propsGyro.includes(v.prop)) {
    return null;
}

let parsed = null;
try {
    parsed = JSON.parse(v.value);
} catch(e) {
    node.warn('Gyro : impossible de parser : ' + v.value);
    return null;
}

if (!parsed) return null;

let gx, gy, gz;
if (Array.isArray(parsed)) {
    if (parsed.length < 3) return null;
    gx = parsed[0]; gy = parsed[1]; gz = parsed[2];
} else if (typeof parsed === 'object') {
    gx = (parsed.x !== undefined) ? parsed.x : 0;
    gy = (parsed.y !== undefined) ? parsed.y : 0;
    gz = (parsed.z !== undefined) ? parsed.z : 0;
} else {
    return null;
}

msg.gyroGx = gx;
msg.gyroGy = gy;
msg.gyroGz = gz;
msg.gyroGxReal = (gx / 100).toFixed(2);
msg.gyroGyReal = (gy / 100).toFixed(2);
msg.gyroGzReal = (gz / 100).toFixed(2);
msg.gyroTs = Date.now();

return msg;

/*
 * Dispatch Gyro -> UI
 * --------------------
 * Envoie 3 messages séparés (Gx, Gy, Gz) vers les ui-text.
 * Version : 2.0 - 2026-04-28 - Vincent Philippe
 */
const gx = String(msg.gyroGxReal !== undefined ? msg.gyroGxReal : '-');
const gy = String(msg.gyroGyReal !== undefined ? msg.gyroGyReal : '-');
const gz = String(msg.gyroGzReal !== undefined ? msg.gyroGzReal : '-');

return [
    { payload: gx },
    { payload: gy },
    { payload: gz }
];

/*
 * Extraire Mag - v1.0
 * --------------------
 * Chemin     : flux Diag_SE_Statut
 * Objectif   : extraire le cap magnétique depuis la trame VPIV
 *
 * Trames traitées :
 *   $F:Mag:DataContMg:*:1850#       cap continu  (degrés×10)
 *   $F:Mag:DataMoyMg:*:1848#        cap moyenné  (degrés×10)
 *   $F:Mag:DataContGeo:*:1830#      cap géo continu
 *   $F:Mag:DataMoyGeo:*:1820#       cap géo moyenné
 *
 * Unités : degrés×10 → diviser par 10 pour degrés réels
 *          Ex: 1850 → 185.0° (Sud)
 * Version : 1.0 - 2026-04-28 - Vincent Philippe
 */

const v = msg.vpiv;
if (!v) return null;

const propsDonnees = ['DataContMg','DataMoyMg','DataContGeo','DataMoyGeo','dataContBrut'];
if (!propsDonnees.includes(v.prop)) {
    return null;
}

msg.magPROP   = v.prop;
msg.magCapRaw = v.value;

if (v.prop !== 'dataContBrut') {
    const raw = parseInt(v.value, 10);
    if (isNaN(raw)) {
        node.warn('Mag : valeur cap non entière : ' + v.value);
        return null;
    }
    msg.magCapDeg  = (raw / 10).toFixed(1);
    const deg      = raw / 10;
    const dirs     = ['N','NE','E','SE','S','SO','O','NO','N'];
    msg.magCapCard = dirs[Math.round(deg / 45) % 8];
} else {
    msg.magCapDeg  = '-';
    msg.magCapCard = '-';
}

return msg;

/*
 * Dispatch Mag -> UI
 * -------------------
 * 3 sorties : cap degrés, point cardinal, propriété reçue
 * Version : 1.0 - 2026-04-28 - Vincent Philippe
 */
const deg  = String(msg.magCapDeg  !== undefined ? msg.magCapDeg  : '-');
const card = String(msg.magCapCard !== undefined ? msg.magCapCard : '-');
const prop = String(msg.magPROP    !== undefined ? msg.magPROP    : '-');

return [
    { payload: deg  },
    { payload: card },
    { payload: prop }
];

/*
 * NOM    : UI_Badge_Urgence_DiagSE
 * TAB    : Diag_SE_Statut
 * ROLE   : Badge d'etat urgence pour la page Diag-SE. Ce flux ne passe
 *          PAS par Gtion_EtatGlobal_V1 (abonnement MQTT brut separe),
 *          donc pas de msg.urgence deja calcule disponible ici -- lit
 *          directement global.RZ_Urg. Declenche a chaque trame
 *          SE/statut recue (frequent, Gyro/Mag en continu) : suffisant
 *          pour un badge, pas besoin d'un declencheur dedie.
 * VERSION: 1.0 - 06/08/2026 - Vincent Philippe / Claude
 */
const rzUrg = global.get('RZ_Urg') || {};
const active = !!(rzUrg.statut && (rzUrg.statut['*'] === 'active' || rzUrg.statut._last === 'active'));
msg.payload = active ? '🔴 Urgence' : '🟢 OK';
return msg;

/*
 * NOM    : UI_Badges_CfgS_DiagSE
 * TAB    : Diag_SE_Statut
 * ROLE   : Badges Mode/Pilotage pour la page Diag-SE. Meme principe que
 *          UI_Badge_Urgence_DiagSE : ce flux ne passe pas par
 *          Gtion_EtatGlobal_V1, lecture directe de global.RZ_CfgS.
 *          Declenche a chaque trame SE/statut recue (frequent).
 * VERSION: 1.0 - 06/08/2026 - Vincent Philippe / Claude
 */
const LABELS_MODE_RZ = { '0':'⏹️ Arret','1':'🌙 Veille','2':'📍 Fixe','3':'🚶 Deplacement','4':'🤖 Autonome','5':'⚠️ Erreur' };
const LABELS_TYPE_PTGE = { '0':'🖥️ Ecran','1':'🎙️ Vocale','2':'🎮 Joystick','3':'🦮 Laisse','4':'🦮🎙️ Laisse+Vocale' };

const rzCfgS = global.get('RZ_CfgS') || {};
function lireCfgS(prop) {
    const p = rzCfgS[prop];
    if (!p) return undefined;
    return p._last !== undefined ? p._last : p['*'];
}

const modeRZ = lireCfgS('modeRZ');
const typePtge = lireCfgS('typePtge');

return [
    { payload: LABELS_MODE_RZ[modeRZ] || 'inconnu' },
    { payload: LABELS_TYPE_PTGE[typePtge] || 'inconnu' }
];

// Chargement exemple de variables complexes

let variables = {
    EXPR: {
        type: "complex",
        properties: {
            "Bonjour": {
                actions: [
                    {
                        device: "app-SE",
                        type: "TTS",
                        value: "Bonjour"
                    }
                ]
            },
            "Oui": {
                actions: [
                    {
                        device: "app-SE",
                        type: "TTS",
                        value: "Oui"
                    },
                    {
                        device: "app-A",
                        type: "LRUB",
                        target: "ar_gd0",
                        color: "orange",
                        mode: "blink"
                    }
                ]
            }
        }
    }
};

global.set("variables", variables);

global.set("modeRZ", "VEILLE");
global.set("emergency", false);

return msg;

let vars = global.get("variables") || {};
let v = msg.payload.variable;
let p = msg.payload.property;

if (!vars[v]) {
    msg.error = "UNKNOWN_VARIABLE";
    return [null, msg];
}

if (!vars[v].properties[p]) {
    msg.error = "UNKNOWN_PROPERTY";
    return [null, msg];
}

msg.plan = {
    intent: `${v}:${p}`,
    actions: vars[v].properties[p].actions,
    meta: {
        source: msg.payload.source || "UNKNOWN",
        priority: "NORMAL"
    }
};

return [msg, null];

let modeRZ = global.get("modeRZ");
let emergency = global.get("emergency");

let accepted = [];
let refused = [];

for (let act of msg.plan.actions) {

    if (act.type === "MTR") {
        if (emergency === true) {
            refused.push({action: act, reason: "EMERGENCY"});
            continue;
        }
        if (!["VEILLE", "DEPLACEMENT"].includes(modeRZ)) {
            refused.push({action: act, reason: "MODE_INCOMPATIBLE"});
            continue;
        }
    }

    if (act.type === "SERVO") {
        if (!["FIXE", "VEILLE", "DEPLACEMENT"].includes(modeRZ)) {
            refused.push({action: act, reason: "MODE_INCOMPATIBLE"});
            continue;
        }
    }

    accepted.push(act);
}

if (accepted.length === 0) {
    msg.status = "REFUSED";
    msg.refused = refused;
    return [null, msg];
}

msg.status = "ACCEPTED";
msg.acceptedActions = accepted;
return [msg, null];

let vpivs = [];

for (let act of msg.acceptedActions) {
    vpivs.push({
        vpiv: {
            app: act.device,
            var: act.type,
            prop: act.target || "",
            value: act.value || {
                color: act.color,
                mode: act.mode
            }
        }
    });
}

msg.vpivs = vpivs;
return msg;
